<script setup>
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue';
import { CategoryTree } from '../services/categories.js';
import StoreCategoryBranch from './StoreCategoryBranch.vue';
import Icon from './Icon.vue';
const props=defineProps({tree:{type:Object,required:true},selected:{type:String,default:''},mode:{type:String,default:'chips'},labels:{type:Object,default:()=>({})}});
const emit=defineEmits(['select']);
const root=ref(null),drawer=ref(null),opener=ref(null),open=ref(false),expanded=ref('');
const roots=computed(()=>props.tree.roots()),trail=computed(()=>props.tree.trail(props.selected)),rows=computed(()=>props.tree.rows());
const text=computed(()=>({all:'Todos los productos',title:'Categorías',open:'Filtrar por categoría',close:'Cerrar filtros',viewAll:'Ver todo',...props.labels}));
const levels=computed(()=>[{parent:null,items:roots.value},...trail.value.map(parent=>({parent,items:props.tree.children(parent)})).filter(level=>level.items.length)]);
const selectedIds=computed(()=>new Set(trail.value.map(CategoryTree.id)));
const expandedCategory=computed(()=>props.tree.get(expanded.value));
const isPanel=computed(()=>props.mode==='drawer'||props.mode==='sidebar');
let previousBodyOverflow='';
watch(open,value=>{if(value){previousBodyOverflow=document.body.style.overflow;document.body.style.overflow='hidden';}else document.body.style.overflow=previousBodyOverflow;},{flush:'sync'});
function select(value){emit('select',CategoryTree.id(value));expanded.value='';closePanel();}
async function openPanel(){open.value=true;await nextTick();drawer.value?.querySelector('button')?.focus();}
function closePanel(){const wasOpen=open.value;open.value=false;if(wasOpen)nextTick(()=>opener.value?.focus());}
function handleKeys(event){
 if(event.key==='Escape'){if(open.value||expanded.value)event.stopPropagation();if(open.value){event.preventDefault();closePanel();}if(expanded.value){event.preventDefault();const id=expanded.value;expanded.value='';nextTick(()=>root.value?.querySelector(`[data-category-toggle="${id}"]`)?.focus());}return;}
 if(event.key!=='Tab'||!open.value)return;
 const focusable=[...drawer.value.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled])')].filter(el=>el.offsetParent!==null);
 const first=focusable[0],last=focusable.at(-1);
 if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}
}
function outside(event){if(expanded.value&&!root.value?.contains(event.target))expanded.value='';}
function focusOut(event){if(expanded.value&&!event.currentTarget.contains(event.relatedTarget))expanded.value='';}
watch(()=>props.mode,()=>{open.value=false;expanded.value='';});
onMounted(()=>document.addEventListener('pointerdown',outside));onUnmounted(()=>{document.removeEventListener('pointerdown',outside);if(open.value)document.body.style.overflow=previousBodyOverflow;});
</script>
<template>
 <div v-if="roots.length" ref="root" class="store-category-picker" :class="'category-mode-'+mode" @keydown="handleKeys">
  <nav v-if="mode==='chips'" class="category-chip-levels" :aria-label="text.title">
   <div v-for="(level,index) in levels" :key="level.parent?._id||'root'" class="category-chip-level">
    <span v-if="level.parent" class="category-level-label">{{tree.label(level.parent)}}</span>
    <div class="store-categories"><button type="button" :class="{selected:level.parent?selected===CategoryTree.id(level.parent):!selected}" :aria-pressed="level.parent?selected===CategoryTree.id(level.parent):!selected" @click="select(level.parent||'')">{{level.parent?text.viewAll:text.all}}</button><button v-for="item in level.items" :key="CategoryTree.id(item)" type="button" :class="{selected:selectedIds.has(CategoryTree.id(item))}" :aria-pressed="selectedIds.has(CategoryTree.id(item))" @click="select(item)">{{item.name}}</button></div>
   </div>
  </nav>
  <label v-else-if="mode==='select'" class="category-select-control"><span>{{text.title}}</span><select :value="selected" @change="select($event.target.value)"><option value="">{{text.all}}</option><option v-for="item in rows" :key="CategoryTree.id(item)" :value="CategoryTree.id(item)">{{tree.label(item)}}</option></select></label>
  <nav v-else-if="mode==='navbar'" class="category-navbar" :aria-label="text.title" @focusout="focusOut">
   <ul class="category-navbar-roots"><li><button type="button" class="category-nav-select" :class="{selected:!selected}" @click="select('')">{{text.all}}</button></li><li v-for="item in roots" :key="CategoryTree.id(item)"><div class="category-nav-root"><button type="button" class="category-nav-select" :class="{selected:selectedIds.has(CategoryTree.id(item))}" :aria-current="selected===CategoryTree.id(item)?'true':undefined" @click="select(item)">{{item.name}}</button><button v-if="tree.children(item).length" type="button" class="category-nav-expand" :aria-label="(expanded===CategoryTree.id(item)?'Cerrar':'Abrir')+' subcategorías de '+item.name" :aria-expanded="expanded===CategoryTree.id(item)" :data-category-toggle="CategoryTree.id(item)" @click="expanded=expanded===CategoryTree.id(item)?'':CategoryTree.id(item)"><Icon name="chevron-down" :size="14"/></button></div></li></ul>
   <div v-if="expandedCategory" class="category-mega-panel"><div class="category-mega-heading"><strong>{{expandedCategory.name}}</strong><button type="button" @click="select(expandedCategory)">{{text.viewAll}}<Icon name="arrow-right" :size="15"/></button></div><ul class="category-mega-tree"><StoreCategoryBranch v-for="item in tree.children(expandedCategory)" :key="CategoryTree.id(item)" :category="item" :tree="tree" :selected="selected" @select="select"/></ul></div>
  </nav>
  <template v-else-if="isPanel">
   <button ref="opener" type="button" class="category-filter-button" :aria-expanded="open" @click="openPanel"><Icon name="filter" :size="17"/>{{text.open}}<span v-if="selected" class="category-filter-count">1</span></button>
   <aside v-if="mode==='sidebar'" class="category-persistent-panel" :aria-label="text.title"><h3>{{text.title}}</h3><button type="button" class="category-all-button" :class="{selected:!selected}" @click="select('')">{{text.all}}</button><ul class="category-tree-list"><StoreCategoryBranch v-for="item in roots" :key="CategoryTree.id(item)" :category="item" :tree="tree" :selected="selected" @select="select"/></ul></aside>
   <div v-if="open" class="category-drawer-layer"><button type="button" class="category-drawer-backdrop" tabindex="-1" :aria-label="text.close" @click="closePanel"></button><section ref="drawer" class="category-drawer" role="dialog" aria-modal="true" :aria-label="text.title"><header><h2>{{text.title}}</h2><button type="button" :aria-label="text.close||'Cerrar categorías'" :title="text.close||'Cerrar categorías'" @click="closePanel"><Icon name="close" :size="22"/></button></header><div class="category-drawer-scroll"><button type="button" class="category-all-button" :class="{selected:!selected}" @click="select('')">{{text.all}}</button><ul class="category-tree-list"><StoreCategoryBranch v-for="item in roots" :key="CategoryTree.id(item)" :category="item" :tree="tree" :selected="selected" @select="select"/></ul></div></section></div>
  </template>
 </div>
</template>
<style scoped>
.store-category-picker{min-width:0;color:var(--store-text)}.category-chip-levels{margin-bottom:26px}.category-chip-level+.category-chip-level{border-top:1px solid var(--store-line);padding-top:12px;margin-top:13px}.category-chip-level .store-categories{margin:8px 0 0}.category-level-label{display:block;font-size:.68rem;line-height:1.5;color:var(--store-muted);overflow-wrap:anywhere}.category-select-control{display:flex;align-items:center;gap:15px;max-width:560px;font-size:.76rem;margin-bottom:27px}.category-select-control>span{font-weight:600}.category-select-control select{min-width:0;flex:1;background:var(--store-surface);color:var(--store-text);border:1px solid var(--store-line);border-radius:7px;padding:12px 35px 12px 13px;font:inherit}.category-navbar{position:relative;min-width:0}.category-navbar-roots{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:4px 17px;align-items:center}.category-navbar-roots>li{min-width:0}.category-nav-root{display:flex;align-items:center;gap:0}.category-nav-select,.category-nav-expand{border:0;background:transparent;color:var(--store-muted);font:inherit;font-size:.76rem}.category-nav-select{padding:12px 2px;text-align:start;overflow-wrap:anywhere}.category-nav-select.selected{color:var(--store-primary);font-weight:700}.category-nav-expand{display:grid;place-items:center;width:28px;height:38px}.category-nav-expand svg{transform:rotate(90deg)}.category-nav-expand[aria-expanded=true] svg{transform:rotate(-90deg)}.category-nav-expand[aria-expanded=true]{color:var(--store-primary);background:var(--store-surface-alt);border-radius:6px}.category-mega-panel{position:absolute;top:calc(100% + 1px);left:0;right:0;z-index:10;border:1px solid var(--store-line);border-radius:0 0 12px 12px;background:var(--store-surface);box-shadow:0 16px 32px #00000014;padding:20px;max-height:min(65vh,470px);overflow:auto}.category-mega-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;border-bottom:1px solid var(--store-line);padding-bottom:12px;margin-bottom:12px}.category-mega-heading strong{font-size:.86rem;overflow-wrap:anywhere}.category-mega-heading button{display:flex;align-items:center;gap:8px;flex:none;border:0;background:transparent;color:var(--store-primary);font-size:.73rem}.category-mega-tree{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(min(210px,100%),1fr));align-items:start;gap:10px 28px}.category-filter-button{display:inline-flex;align-items:center;gap:10px;padding:11px 15px;border:1px solid var(--store-line);border-radius:8px;background:var(--store-surface);color:var(--store-text);font-size:.77rem;max-width:100%;overflow-wrap:anywhere}.category-filter-count{display:grid;place-items:center;min-width:19px;height:19px;border-radius:50%;background:var(--store-primary);color:var(--store-on-primary);font-size:.61rem}.category-mode-drawer{margin-bottom:25px}.category-persistent-panel{position:sticky;top:calc(var(--store-header-offset,82px) + 20px);max-height:calc(100dvh - var(--store-header-offset,82px) - 40px);overflow:auto;border:1px solid var(--store-line);border-radius:var(--store-radius);padding:18px;background:var(--store-surface)}.category-persistent-panel h3{margin:0 0 13px;font-size:.91rem}.category-tree-list{list-style:none;padding:0;margin:8px 0 0}.category-all-button{display:block;text-align:start;width:100%;padding:11px 12px;background:transparent;color:var(--store-text);border:1px solid var(--store-line);border-radius:7px;font-size:.76rem}.category-all-button.selected{background:var(--store-primary);color:var(--store-on-primary);border-color:var(--store-primary)}.category-mode-sidebar>.category-filter-button{display:none}.category-drawer-layer{position:fixed;inset:0;z-index:85;direction:inherit}.category-drawer-backdrop{position:absolute;inset:0;border:0;background:#00000055;cursor:default}.category-drawer{position:absolute;inset-block:0;left:0;width:min(375px,calc(100vw - 32px));display:flex;flex-direction:column;box-shadow:12px 0 35px #00000022;background:var(--store-surface);color:var(--store-text);direction:inherit}.category-drawer header{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:22px;border-bottom:1px solid var(--store-line);flex:none}.category-drawer h2{font-size:1.1rem;margin:0}.category-drawer header button{width:36px;height:36px;display:grid;place-items:center;border:0;border-radius:50%;background:var(--store-surface-alt);color:var(--store-text)}.category-drawer-scroll{padding:20px;overflow:auto;min-height:0;overscroll-behavior:contain}.store-category-picker button:focus-visible,.store-category-picker select:focus-visible{outline:2px solid var(--store-primary);outline-offset:2px}@media(max-width:850px){.category-mode-sidebar>.category-filter-button{display:inline-flex}.category-persistent-panel{display:none}.category-mode-sidebar{margin-bottom:25px}}@media(max-width:500px){.category-navbar-roots{gap:0 11px}.category-nav-select{font-size:.69rem}.category-mega-panel{padding:14px;max-height:55dvh}.category-select-control{align-items:stretch;flex-direction:column;gap:8px;font-size:.74rem}.category-chip-level .store-categories{padding-bottom:6px}.category-drawer-scroll{padding:15px}}
</style>
